    3 => GHOSTTY_KITTY_IMAGE_FORMAT_GRAY_ALPHA,
    4 => GHOSTTY_KITTY_IMAGE_FORMAT_GRAY,
    2147483647 => GHOSTTY_KITTY_IMAGE_FORMAT_MAX_VALUE,
    _ => throw ArgumentError(
      'Unknown value for GhosttyKittyImageFormat: $value',
    ),
  };
