    4 => GHOSTTY_SELECTION_ADJUST_HOME,
    5 => GHOSTTY_SELECTION_ADJUST_END,
    6 => GHOSTTY_SELECTION_ADJUST_PAGE_UP,
    7 => GHOSTTY_SELECTION_ADJUST_PAGE_DOWN,
